package de.corporate.lc.lc.service; import de.corporate.lc.lc.domain.*; import de.corporate.lc.lc.repository.*; import de.corporate.lc.swift.Mt707Parser; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class AmendmentService {private final AmendmentRepository amendments;private final LetterOfCreditRepository lcs;private final Mt707Parser parser;public AmendmentService(AmendmentRepository a,LetterOfCreditRepository l,Mt707Parser p){amendments=a;lcs=l;parser=p;}@Transactional public Amendment importMt707(String raw){var p=parser.parse(raw);LetterOfCredit lc=lcs.findAll().stream().filter(x->x.getReference().equals(p.lcReference())).findFirst().orElseThrow(()->new IllegalArgumentException("Original LC not found: "+p.lcReference()));Amendment a=p.amendment();a.setLetterOfCredit(lc);if(a.getNewExpiryDate()!=null){lc.setExpiryDate(a.getNewExpiryDate());if(a.getNewExpiryPlace()!=null&&!a.getNewExpiryPlace().isBlank())lc.setExpiryPlace(a.getNewExpiryPlace());}if(a.getNewLatestShipmentDate()!=null)lc.setLatestShipmentDate(a.getNewLatestShipmentDate());if(a.getAmountIncrease()!=null&&lc.getAmount()!=null)lc.setAmount(lc.getAmount().add(a.getAmountIncrease()));if(a.getAmountDecrease()!=null&&lc.getAmount()!=null)lc.setAmount(lc.getAmount().subtract(a.getAmountDecrease()));lcs.save(lc);return amendments.save(a);}public List<Amendment> forLc(UUID id){return amendments.findByLetterOfCreditIdOrderByImportedAtDesc(id);}}
